    /*
     * Add to the Datasets
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Tag
     */
    public Tag addToDatasets( UUID parentId, DataSet addTo ) {
	    LOGGER.info("handling AssignDatasetsToTagEvent - " );
	    
	    Tag parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, addTo.getDataSetId());
	    
	    parentEntity.getDatasets().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

